"960\" y2=\"560\" stroke=\"#ef4444\" stroke-width=\"5\"/><text x=\"800\" y=\"700\" font-size=\"20\" fill=\"#10b981\" text-anchor=\"middle\" font-family=\"Arial\">order grows inside</text><text x=\"800\" y=\"740\" font-size=\"18\" fill=\"#888\" text-anchor=\"middle\" font-family=\"Arial\">(a living embryo)</text><text x=\"550\" y=\"920\" font-size=\"22\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"Arial\">Life is open. That is the whole answer.</text></svg>",
